mapper.sql:
WHERE 1=1

  AND (l.owner_id=#{scope.userId} OR l.created_by=#{scope.userId}

    OR o.dept_id IN #{d}
    OR a.dept_id IN #{d}
    OR (l.owner_id IS NULL AND l.target_dept_id IN #{d})
  )

AND (l.company_name LIKE CONCAT('%',#{keyword},'%') OR l.contact_name LIKE CONCAT('%',#{keyword},'%'))
AND l.status=#{status}

WHERE c.owner_id IS NOT NULL 
AND (b.title LIKE CONCAT('%',#{keyword},'%') OR c.company_name LIKE CONCAT('%',#{keyword},'%'))
AND b.customer_id=#{customerId}
AND b.stage=#{stage}
